  const withVoucher = applyVoucher(inv, { code: 'SAVE10', amount: 1000 }).value;
  const issued = issueInvoice(withVoucher, []).value;
  const totals = invoiceTotals(issued).value;

  const result = overdueInvoices([issued], '2025-04-15');

  assert.equal(result.length, 1);
  assert.equal(result[0].due, totals.total);
});

// VAT Summary tests

test('vatSummary returns empty array when no invoices', () => {
  const result = vatSummary([]);

  assert.equal(Array.isArray(result), true);
  assert.equal(result.length, 0);
});

test('vatSummary excludes draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
