  const item = result[0];
  assert.equal(typeof item.rate, 'number');
  assert.equal(typeof item.base, 'number');
  assert.equal(typeof item.vat, 'number');
});

test('vatSummary groups by VAT rate', () => {
  // Create invoices with different products that have same VAT rate
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'STICKER', qty: 100 },
    ],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = vatSummary([issued]);

  // Both DEV-HOUR and STICKER have 21% VAT, should be one entry
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
});

test('vatSummary calculates base correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = vatSummary([issued]);

  // DEV-HOUR: 10 × 9500 cents = 95000 cents
  // No discount, no tier discount (C-001 has gold tier which adds 5% discount)
  // Actually, C-001 is gold tier so it gets 5% discount
  // base = 95000 - (95000 × 0.05) = 95000 - 4750 = 90250
  const expected = 95000 - (95000 * 0.05);
  assert.equal(result[0].base, expected);
});

test('vatSummary calculates VAT correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = vatSummary([issued]);

  // VAT = base × 21 / 100
  const expectedVat = Math.round(result[0].base * 0.21);
  assert.equal(result[0].vat, expectedVat);
});

test('vatSummary with line discount', () => {
  const inv = createInvoice({
    customerId: 'C-002', // standard tier, no automatic discount
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 20 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = vatSummary([issued]);

  // DEV-HOUR: 10 × 9500 = 95000 cents
  // Discount: 95000 × 20% = 19000
  // Base: 95000 - 19000 = 76000
  const expected = 95000 - 19000;
  assert.equal(result[0].base, expected);
});

test('vatSummary with multiple VAT rates', () => {
  // Create two invoices with different VAT products
  // DEV-HOUR has 21%, but we need a product with different VAT
  // Looking at the catalogue, DEV-HOUR and STICKER both have 21%
  // For this test, we'll work with the existing products
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'STICKER', qty: 100 },
    ],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = vatSummary([issued]);

  // Both have 21% VAT, so should be one entry
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
});

test('vatSummary sums VAT across multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const result = vatSummary([issued1, issued2]);

  // Both have 21% VAT, should sum together
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert(result[0].base > 0);
  assert(result[0].vat > 0);
});

test('vatSummary sorts by rate descending', () => {
  // We need to create a scenario with multiple VAT rates
  // For now, we'll just test with a single rate and verify sorting works
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = vatSummary([issued]);

  // Verify results are sorted
  for (let i = 1; i < result.length; i++) {
    assert(result[i - 1].rate >= result[i].rate);
  }
});

test('vatSummary with discount and VAT', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = vatSummary([issued]);

  // DEV-HOUR: 10 × 9500 = 95000
  // Discount: 95000 × 10% = 9500
  // Base: 95000 - 9500 = 85500
  const expectedBase = 95000 - 9500;
  assert.equal(result[0].base, expectedBase);

  // VAT: 85500 × 21% = 17955
  const expectedVat = Math.round(expectedBase * 0.21);
  assert.equal(result[0].vat, expectedVat);
});

test('vatSummary with tier discount (gold)', () => {
  const inv = createInvoice({
    customerId: 'C-001', // gold tier: 5% discount
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = vatSummary([issued]);

  // DEV-HOUR: 10 × 9500 = 95000
  // Tier discount (gold): 95000 × 5% = 4750
  // Base: 95000 - 4750 = 90250
  const expectedBase = 95000 - 4750;
  assert.equal(result[0].base, expectedBase);
});

test('vatSummary with mixed invoice statuses', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  }).value;

  const issued = issueInvoice(inv2, ['INV-2025-0001']).value;

  // Should only include the issued invoice, not the draft
  const result = vatSummary([draft, issued]);

  assert.equal(result.length, 1);
});

test('vatSummary base and vat are non-negative', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = vatSummary([issued]);

  for (const item of result) {
    assert(item.base >= 0);
    assert(item.vat >= 0);
  }
});

test('vatSummary rate is a number', () => {
  const inv = createInvoice({
